const cellOpts = (text, align, color, bold, bg) => ({ text, options: { fill: { color: bg || C.white }, color: color || C.slate800, bold: !!bold, fontSize: 10, align: align || "left", fontFace: "Calibri", margin: [3, 5, 3, 5] } });

