const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The 2025 LLM Usage Landscape";
pres.author = "LLM Market Analysis";

// Slide: 10" x 5.625"
const SH = 5.625;

// ── Color Palette ──
const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  cyan:      "06B6D4",
  cyanDark:  "0891B2",
  cyanLight: "ECFEFF",
  violet:    "8B5CF6",
  violetLt:  "F5F3FF",
  amber:     "F59E0B",
  amberLt:   "FFFBEB",
  emerald:   "10B981",
  emeraldLt: "ECFDF5",
  rose:      "F43F5E",
  red:       "EF4444",
  redLt:     "FEF2F2",
  blue:      "3B82F6",
  indigo:    "6366F1",
  pink:      "EC4899",
  stone:     "78716C",
  slate100:  "F1F5F9",
  slate200:  "E2E8F0",
  slate400:  "94A3B8",
  slate500:  "64748B",
  slate600:  "475569",
  slate700:  "334155",
  slate800:  "1E293B",
};

// ── Helpers ──
const mkShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 });
const mkShadowLg = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.1 });

function addHeader(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
  slide.addText(title, { x: 0.6, y: 0.12, w: 8.8, h: 0.6, fontSize: 26, fontFace: "Arial Black", color: C.white, margin: 0 });
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0.85, w: 10, h: 0.04, fill: { color: C.cyan } });
}

function addFooter(slide, text) {
  slide.addText(text || "Source: OpenRouter Rankings  |  Latest week of March 2025", {
    x: 0.5, y: SH - 0.4, w: 9, h: 0.25, fontSize: 9, fontFace: "Calibri", color: C.slate500, align: "right", margin: 0
  });
}

// ═══════════════════════════════════════════════════════
// SLIDE 1: Title
// ═══════════════════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { color: C.darkBg };

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.05, fill: { color: C.cyan } });

// Big stat
s1.addText("26T+", { x: 0.5, y: 0.55, w: 9, h: 1.1, fontSize: 72, fontFace: "Arial Black", color: C.cyan, align: "center", margin: 0 });
s1.addText("tokens processed this week", { x: 0.5, y: 1.6, w: 9, h: 0.35, fontSize: 18, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

// Title
s1.addText("The 2025 LLM Usage Landscape", { x: 0.5, y: 2.45, w: 9, h: 0.7, fontSize: 36, fontFace: "Arial Black", color: C.white, align: "center", margin: 0 });
s1.addText("Real-World Data from OpenRouter", { x: 0.5, y: 3.1, w: 9, h: 0.4, fontSize: 22, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

// Stat boxes - no overlap, 0.2" gaps between them
const boxW = 2.2;
const boxGap = 0.2;
const boxTotalW = 3 * boxW + 2 * boxGap;
const boxStartX = (10 - boxTotalW) / 2;

s1.addShape(pres.shapes.RECTANGLE, { x: boxStartX, y: 3.85, w: boxW, h: 0.7, fill: { color: C.darkBg2 } });
s1.addShape(pres.shapes.RECTANGLE, { x: boxStartX + boxW + boxGap, y: 3.85, w: boxW, h: 0.7, fill: { color: C.darkBg2 } });
s1.addShape(pres.shapes.RECTANGLE, { x: boxStartX + 2 * (boxW + boxGap), y: 3.85, w: boxW, h: 0.7, fill: { color: C.darkBg2 } });

s1.addText("8 Providers", { x: boxStartX, y: 3.9, w: boxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.cyan, align: "center", margin: 0 });
s1.addText("in the top 10", { x: boxStartX, y: 4.2, w: boxW, h: 0.25, fontSize: 10, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

s1.addText("54% Chinese", { x: boxStartX + boxW + boxGap, y: 3.9, w: boxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.violet, align: "center", margin: 0 });
s1.addText("provider share", { x: boxStartX + boxW + boxGap, y: 4.2, w: boxW, h: 0.25, fontSize: 10, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

s1.addText("5 Coding Apps", { x: boxStartX + 2 * (boxW + boxGap), y: 3.9, w: boxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.emerald, align: "center", margin: 0 });
s1.addText("in top 10", { x: boxStartX + 2 * (boxW + boxGap), y: 4.2, w: boxW, h: 0.25, fontSize: 10, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

s1.addText("Source: OpenRouter Rankings  |  Latest week of March 2025  |  Data from millions of users", {
  x: 0.5, y: 4.8, w: 9, h: 0.3, fontSize: 11, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0
});

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: SH - 0.05, w: 10, h: 0.05, fill: { color: C.cyan } });


// ═══════════════════════════════════════════════════════
// SLIDE 2: Top 10 Models
// ═══════════════════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { color: C.lightBg };
addHeader(s2, "This Week's Top 10 Models");

