  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  cyan:      "06B6D4",
  cyanDark:  "0891B2",
  cyanLight: "ECFEFF",
  violet:    "8B5CF6",
  violetLt:  "F5F3FF",
  amber:     "F59E0B",
  amberLt:   "FFFBEB",
  emerald:   "10B981",
  emeraldLt: "ECFDF5",
  rose:      "F43F5E",
  red:       "EF4444",
  redLt:     "FEF2F2",
  blue:      "3B82F6",
  indigo:    "6366F1",
  pink:      "EC4899",
  stone:     "78716C",
  slate100:  "F1F5F9",
  slate200:  "E2E8F0",
  slate400:  "94A3B8",
  slate500:  "64748B",
  slate600:  "475569",
  slate700:  "334155",
  slate800:  "1E293B",
};

// ── Helpers ──
