s1.addText("5 Coding Apps", { x: boxStartX + 2 * (boxW + boxGap), y: 3.9, w: boxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.emerald, align: "center", margin: 0 });
s1.addText("in top 10", { x: boxStartX + 2 * (boxW + boxGap), y: 4.2, w: boxW, h: 0.25, fontSize: 10, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

