// ═══════════════════════════════════════════════════════
// SLIDE 2: Top 10 Models
// ═══════════════════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { color: C.lightBg };
addHeader(s2, "This Week's Top 10 Models");

const models = [
  { rank: "1",  name: "MiMo-V2-Pro",          provider: "Xiaomi",    tokens: "3.96T", wow: "+165%", wowPositive: true },
  { rank: "2",  name: "Step 3.5 Flash (free)", provider: "Stepfun",   tokens: "1.49T", wow: "+1%",   wowPositive: true },
  { rank: "3",  name: "MiniMax M2.7",          provider: "MiniMax",   tokens: "1.29T", wow: "+253%", wowPositive: true },
  { rank: "4",  name: "DeepSeek V3.2",         provider: "DeepSeek",  tokens: "1.24T", wow: "+9%",   wowPositive: true },
  { rank: "5",  name: "Claude Sonnet 4.6",     provider: "Anthropic", tokens: "1.04T", wow: "-0%",   wowPositive: false },
  { rank: "6",  name: "Claude Opus 4.6",       provider: "Anthropic", tokens: "995B",  wow: "+2%",   wowPositive: true },
  { rank: "7",  name: "Gemini 3 Flash Preview",provider: "Google",    tokens: "972B",  wow: "+3%",   wowPositive: true },
  { rank: "8",  name: "GLM 5 Turbo",           provider: "Zhipu",     tokens: "968B",  wow: "-6%",   wowPositive: false },
  { rank: "9",  name: "MiniMax M2.5",          provider: "MiniMax",   tokens: "909B",  wow: "-30%",  wowPositive: false },
  { rank: "10", name: "Grok 4.1 Fast",         provider: "x-ai",     tokens: "599B",  wow: "+32%",  wowPositive: true },
];

const hdrOpts = (text, align) => ({ text, options: { fill: { color: C.darkBg }, color: C.white, bold: true, fontSize: 10, align: align || "left", fontFace: "Calibri", margin: [3, 5, 3, 5] } });
const cellOpts = (text, align, color, bold, bg) => ({ text, options: { fill: { color: bg || C.white }, color: color || C.slate800, bold: !!bold, fontSize: 10, align: align || "left", fontFace: "Calibri", margin: [3, 5, 3, 5] } });

const tableRows = [
  [hdrOpts("#"), hdrOpts("Model"), hdrOpts("Provider"), hdrOpts("Weekly Tokens", "right"), hdrOpts("WoW", "center")],
];

models.forEach((m, i) => {
  const bg = i === 0 ? C.cyanLight : (i % 2 === 0 ? C.slate100 : C.white);
  const wowColor = m.wow.startsWith("+") && m.wow !== "+0%" && m.wow !== "-0%" ? C.emerald : (m.wow.startsWith("-") && m.wow !== "-0%" ? C.red : C.slate500);
  tableRows.push([
    cellOpts(m.rank, "center", C.slate700, false, bg),
    cellOpts(m.name, "left", C.slate800, i === 0, bg),
    cellOpts(m.provider, "left", C.slate600, false, bg),
    cellOpts(m.tokens, "right", C.slate800, false, bg),
    cellOpts(m.wow, "center", wowColor, true, bg),
  ]);
});

// Table on left - using wider width for readability
s2.addTable(tableRows, {
  x: 0.5, y: 1.1, w: 5.9,
  colW: [0.4, 1.8, 1.1, 1.2, 0.7],
  border: { pt: 0.5, color: C.slate200 },
  rowH: [0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28],
});

// Key findings panel - ensure 0.5" right margin
const panelX = 6.7;
const panelW = 2.8;
s2.addShape(pres.shapes.RECTANGLE, { x: panelX, y: 1.1, w: panelW, h: 3.85, fill: { color: C.white }, shadow: mkShadow() });

s2.addText("Key Findings", { x: panelX + 0.2, y: 1.2, w: panelW - 0.4, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.slate800, margin: 0 });

// Stat cards with proper gaps
const cardPad = 0.2;
const cardW2 = panelW - 2 * cardPad;
const cardGap = 0.2;
let cardY = 1.6;

// Card 1
s2.addShape(pres.shapes.RECTANGLE, { x: panelX + cardPad, y: cardY, w: cardW2, h: 0.75, fill: { color: C.cyanLight } });
