s2.addText("MiMo-V2-Pro leads with +165% WoW", { x: panelX + cardPad + 0.1, y: cardY + 0.35, w: cardW2 - 0.2, h: 0.3, fontSize: 10, fontFace: "Calibri", color: C.slate700, margin: 0 });

cardY += 0.75 + cardGap;

// Card 3
