s2.addText("+253%", { x: panelX + cardPad + 0.1, y: cardY + 0.03, w: cardW2 - 0.2, h: 0.3, fontSize: 16, fontFace: "Arial Black", color: C.emerald, margin: 0 });
s2.addText("MiniMax M2.7 posted strongest growth", { x: panelX + cardPad + 0.1, y: cardY + 0.35, w: cardW2 - 0.2, h: 0.3, fontSize: 10, fontFace: "Calibri", color: C.slate700, margin: 0 });

cardY += 0.75 + cardGap;

