// Stat boxes: narrow with clear gaps
const bxW = 1.9;
const bxGap = 0.35;
const bxTotal = 3 * bxW + 2 * bxGap;
const bxStart = (SW - bxTotal) / 2;
const bxY = 3.75;

s1.addShape(pres.shapes.RECTANGLE, { x: bxStart, y: bxY, w: bxW, h: 0.7, fill: { color: C.darkBg2 } });
