const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The 2025 LLM Usage Landscape";
pres.author = "LLM Market Analysis";

// Slide: 10" x 5.625"
const SW = 10;
const SH = 5.625;
const MARGIN = 0.5;       // Minimum margin from all edges
const MAX_X = SW - MARGIN; // 9.5
const MAX_Y = SH - MARGIN; // 5.125
const MIN_GAP = 0.3;

// ── Color Palette ──
const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  cyan:      "06B6D4",
  cyanDark:  "0891B2",
  cyanLight: "ECFEFF",
  violet:    "8B5CF6",
  violetLt:  "F5F3FF",
  amber:     "F59E0B",
  amberLt:   "FFFBEB",
  emerald:   "10B981",
  emeraldLt: "ECFDF5",
  rose:      "F43F5E",
  red:       "EF4444",
  blue:      "3B82F6",
  indigo:    "6366F1",
  pink:      "EC4899",
  stone:     "78716C",
  slate100:  "F1F5F9",
  slate200:  "E2E8F0",
  slate400:  "94A3B8",
  slate500:  "64748B",
  slate600:  "475569",
  slate700:  "334155",
  slate800:  "1E293B",
};

const mkShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 });
const mkShadowLg = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.1 });

function addHeader(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: SW, h: 0.85, fill: { color: C.darkBg } });
  slide.addText(title, { x: MARGIN, y: 0.12, w: SW - 2 * MARGIN, h: 0.6, fontSize: 26, fontFace: "Arial Black", color: C.white, margin: 0 });
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0.85, w: SW, h: 0.04, fill: { color: C.cyan } });
}

function addFooter(slide) {
  slide.addText("Source: OpenRouter Rankings  |  Latest week of March 2025", {
    x: MARGIN, y: MAX_Y - 0.2, w: SW - 2 * MARGIN, h: 0.2, fontSize: 9, fontFace: "Calibri", color: C.slate500, align: "right", margin: 0
  });
}


// ═══════════════════════════════════════════════════════
// SLIDE 1: Title
// ═══════════════════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { color: C.darkBg };

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: SW, h: 0.05, fill: { color: C.cyan } });

s1.addText("26T+", { x: MARGIN, y: 0.55, w: SW - 2 * MARGIN, h: 1.0, fontSize: 72, fontFace: "Arial Black", color: C.cyan, align: "center", margin: 0 });
s1.addText("tokens processed this week", { x: MARGIN, y: 1.5, w: SW - 2 * MARGIN, h: 0.35, fontSize: 18, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

s1.addText("The 2025 LLM Usage Landscape", { x: MARGIN, y: 2.3, w: SW - 2 * MARGIN, h: 0.7, fontSize: 36, fontFace: "Arial Black", color: C.white, align: "center", margin: 0 });
s1.addText("Real-World Data from OpenRouter", { x: MARGIN, y: 2.95, w: SW - 2 * MARGIN, h: 0.4, fontSize: 22, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

// Stat boxes: narrow with clear gaps
const bxW = 1.9;
const bxGap = 0.35;
const bxTotal = 3 * bxW + 2 * bxGap;
const bxStart = (SW - bxTotal) / 2;
const bxY = 3.75;

s1.addShape(pres.shapes.RECTANGLE, { x: bxStart, y: bxY, w: bxW, h: 0.7, fill: { color: C.darkBg2 } });
s1.addShape(pres.shapes.RECTANGLE, { x: bxStart + bxW + bxGap, y: bxY, w: bxW, h: 0.7, fill: { color: C.darkBg2 } });
s1.addShape(pres.shapes.RECTANGLE, { x: bxStart + 2 * (bxW + bxGap), y: bxY, w: bxW, h: 0.7, fill: { color: C.darkBg2 } });

s1.addText("8 Providers", { x: bxStart, y: bxY + 0.05, w: bxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.cyan, align: "center", margin: 0 });
s1.addText("in the top 10", { x: bxStart, y: bxY + 0.35, w: bxW, h: 0.25, fontSize: 10, fontFace: "Calibri", color: C.slate400, align: "center", margin: 0 });

s1.addText("54% Chinese", { x: bxStart + bxW + bxGap, y: bxY + 0.05, w: bxW, h: 0.3, fontSize: 14, fontFace: "Arial Black", color: C.violet, align: "center", margin: 0 });
